files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #6e6f72;
  --vt-on-deep: #ffffff;
  --vt-accent: #d6a354;
  --vt-on-accent: #000000;
  --vt-accent-ink: #c12828;
  --vt-accent-on-deep: #fdbb2d;
  --vt-line: #d9d9d9;
  font-family: 'Fira Sans Condensed', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.5;
}

.root, .root *, .root *::before, .root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(button) {
  font: inherit;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  font-family: 'Anton', sans-serif;
  font-weight: 400;
  margin: 0;
}

.root :where(p) {
  margin: 0;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent-on-deep);
  outline-offset: 2px;
}

.sidebar {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  width: 280px;
  background: var(--vt-accent);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 40px 24px;
  z-index: 100;
  text-align: center;
}

.logo {
  margin-bottom: 60px;
}

.logoBrand {
  color: var(--vt-on-accent);
}

.navLinks {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.navLinks a {
  color: var(--vt-on-accent);
  font-size: 18px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 8px 16px;
  border-radius: 100px;
  transition: color 0.3s, background 0.3s;
}

.navLinks a:hover {
  color: var(--vt-surface);
  background: rgba(0, 0, 0, 0.15);
}

.main {
  margin-left: 280px;
}

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  background-size: cover;
  background-position: center;
  background-attachment: fixed;
  border-bottom: 15px solid var(--vt-accent);
  padding: 60px;
  overflow: hidden;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--vt-accent-on-deep), var(--vt-accent-ink));
  opacity: 0.65;
  pointer-events: none;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 640px;
}

.heroKicker {
  color: var(--vt-ink);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  margin-bottom: 16px;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: 74px;
  line-height: 1.1;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.heroTitle em {
  font-style: italic;
}

.heroTagline {
  color: var(--vt-ink);
  font-size: 20px;
  margin-bottom: 32px;
}

.heroButtons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.btnPrimary {
  background: var(--vt-accent-ink);
  border: 2px solid transparent;
  color: var(--vt-surface);
  border-radius: 100px;
  padding: 12px 24px;
  font-weight: 700;
  transition: background 0.3s, color 0.3s;
}

.btnPrimary:hover {
  background: var(--vt-accent-on-deep);
  color: var(--vt-surface);
}

.btnGhost {
  background: transparent;
  border: 2px solid var(--vt-accent-ink);
  color: var(--vt-accent-ink);
  border-radius: 100px;
  padding: 12px 24px;
  font-weight: 700;
  transition: background 0.3s, color 0.3s;
}

.btnGhost:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-surface);
}

.heroCard {
  position: absolute;
  z-index: 2;
  bottom: -60px;
  right: -60px;
  width: 360px;
  height: 360px;
  border: 10px solid var(--vt-accent);
  border-radius: 50%;
  background: var(--vt-surface);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 40px 60px 40px 40px;
  text-align: center;
}

.heroCardImageWrap {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  overflow: hidden;
  border: 10px solid var(--vt-accent);
  margin-bottom: 16px;
  background: var(--vt-surface);
}

.heroCardImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.heroCardText {
  font-size: 14px;
  text-transform: uppercase;
  color: var(--vt-ink-soft);
}

.heroCardPhone {
  font-weight: 700;
  font-size: 22px;
  color: var(--vt-accent-ink);
}

.section {
  padding: 100px 50px;
}

.sectionInner {
  max-width: 1100px;
  margin: 0 auto;
}

.sectionTitle {
  font-size: 46px;
  text-transform: uppercase;
  margin-bottom: 24px;
}

.lead {
  font-size: 20px;
  color: var(--vt-ink-soft);
  max-width: 800px;
  margin-bottom: 40px;
}

.storyGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.storyText p {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.storyImageWrap {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 20px;
  transform: rotate(3deg);
}

.storyImage {
  border-radius: 20px;
  transform: rotate(-3deg);
  object-fit: cover;
  width: 100%;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.serviceCard {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
}

.serviceImage {
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transition: transform 0.3s;
}

.serviceCard:hover .serviceImage {
  transform: scale(1.05);
}

.serviceInfo {
  position: absolute;
  inset: 0;
  margin: 20px;
  border: 1px solid var(--vt-surface);
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 25px 30px;
  transition: border-color 0.3s, border-width 0.3s;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.35), transparent);
}

.serviceCard:hover .serviceInfo {
  border-color: var(--vt-accent);
  border-width: 5px;
}

.serviceTitle {
  color: var(--vt-on-deep);
  font-size: 28px;
  text-transform: uppercase;
}

.servicePrice {
  align-self: flex-end;
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 5px 12px;
  font-size: 14px;
  color: var(--vt-on-accent);
}

.serviceDesc {
  color: var(--vt-on-deep);
  margin-top: 8px;
}

.serviceDuration {
  color: var(--vt-on-deep);
  margin-top: 4px;
  font-size: 14px;
}

.priceGrid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 60px;
  align-items: center;
}

.priceList {
  padding-right: 50px;
}

.priceRow {
  display: flex;
  align-items: baseline;
  margin-bottom: 10px;
}

.priceName {
  font-size: 22px;
  font-weight: 600;
  margin: 0;
}

.priceDots {
  flex: 1;
  border-bottom: 2px dotted var(--vt-ink-soft);
  margin: 0 15px;
  transform: translateY(-6px);
}

.priceValue {
  color: var(--vt-accent-ink);
  font-size: 22px;
}

.priceImageWrap {
  background: var(--vt-accent);
  border-radius: 20px;
  padding: 20px;
}

.priceImage {
  border-radius: 20px;
  width: 100%;
  object-fit: cover;
  transform: rotate(8deg);
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: stretch;
}

.contactInfo {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.social {
  margin-top: 20px;
}

.hoursCard {
  background: var(--vt-accent);
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 40px;
  min-height: 200px;
  text-align: center;
}

.hoursLabel {
  font-size: 16px;
  text-transform: uppercase;
  color: var(--vt-on-accent);
}

.hoursValue {
  font-size: 28px;
  color: var(--vt-on-accent);
}

.footer {
  padding: 80px 50px;
  border-top: 1px solid var(--vt-line);
}

.footerInner {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.areas {
  color: var(--vt-ink-soft);
}

.copyright {
  color: var(--vt-ink-soft);
}

@media (max-width: 991px) {
  .sidebar {
    position: static;
    width: 100%;
    padding: 20px;
    flex-direction: row;
    justify-content: space-between;
  }

  .logo {
    margin-bottom: 0;
  }

  .navLinks {
    flex-direction: row;
    gap: 4px;
  }

  .main {
    margin-left: 0;
  }

  .hero {
    min-height: auto;
    padding: 80px 25px 100px;
  }

  .heroCard {
    display: none;
  }

  .storyGrid,
  .priceGrid,
  .contactGrid {
    grid-template-columns: 1fr;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .section {
    padding: 50px 25px;
  }

  .priceList {
    padding-right: 0;
  }
}
